import type { GeospatialCamera } from "@babylonjs/lite";

const DEG_TO_RAD = Math.PI / 180;

export function centerOnLatLon(camera: GeospatialCamera, latitudeDeg: number, longitudeDeg: number): void {
  const planetRadius = camera.limits.planetRadius;
  const lat = latitudeDeg * DEG_TO_RAD;
  const lon = longitudeDeg * DEG_TO_RAD;
  const cosLat = Math.cos(lat);

  // Babylon Lite's geospatial frame: lat 0/lon 0 is +X, north is +Z,
  // positive longitude (east) is toward -Y.
  const center = {
    x: planetRadius * cosLat * Math.cos(lon),
    y: -planetRadius * cosLat * Math.sin(lon),
    z: planetRadius * Math.sin(lat),
  };

  // Capture the pose before assigning, then apply the same yaw/pitch/radius
  // around the new centre so zoom/heading/tilt are preserved.
  const yaw = camera.yaw;
  const pitch = camera.pitch;
  const radius = camera.radius;

  camera.center = center;
  if (typeof camera._setOrientation === "function") {
    camera._setOrientation(yaw, pitch, radius, center);
  }
}
```

